package net.civeira.phylax.feature.access.userwebauthncredential.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.userwebauthncredential.domain.UserWebauthnCredential;
import net.civeira.phylax.feature.access.userwebauthncredential.domain.valueobject.DeviceNameVO;

class DeviceNameValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of device name of user webauthn credential")
  void test_device_name_value_holder_assign_plain_value() {
    Object holder = new Object();
    DeviceNameValueHolder<Object> value = new DeviceNameValueHolder<>(holder);
    Assertions.assertSame(holder, value.deviceName("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getDeviceNameValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getDeviceName().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.deviceNameNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getDeviceNameValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getDeviceName().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of device name of user webauthn credential")
  void test_device_name_value_holder_assign_value_object() {
    Object holder = new Object();
    DeviceNameValueHolder<Object> value = new DeviceNameValueHolder<>(holder);
    DeviceNameVO vo = DeviceNameVO.from("one");
    Assertions.assertFalse(value.getDeviceNameValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.deviceName(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getDeviceNameValue().orElseThrow());
    Assertions.assertSame(holder, value.deviceName(Optional.empty()));
    Assertions.assertFalse(value.getDeviceNameValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.deviceName(Optional.of(vo)));
    Assertions.assertSame(vo, value.getDeviceNameValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of device name of user webauthn credential against the original")
  void test_device_name_value_holder_read() {
    Object holder = new Object();
    DeviceNameValueHolder<Object> value = new DeviceNameValueHolder<>(holder);
    DeviceNameVO vo = DeviceNameVO.from("one");
    DeviceNameVO other = DeviceNameVO.from("one");
    UserWebauthnCredential original = Mockito.mock(UserWebauthnCredential.class);
    Mockito.when(original.getDeviceNameValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readDeviceName(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readDeviceName(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.deviceName(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readDeviceName(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readDeviceName(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of device name of user webauthn credential")
  void test_device_name_value_holder_unset() {
    Object holder = new Object();
    DeviceNameValueHolder<Object> value = new DeviceNameValueHolder<>(holder);
    DeviceNameVO vo = DeviceNameVO.from("one");
    value.deviceName(vo);
    Assertions.assertSame(holder, value.unsetDeviceNameIfMatches("deviceName_other"));
    Assertions.assertTrue(value.getDeviceNameValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetDeviceNameIfMatches("deviceName"));
    Assertions.assertFalse(value.getDeviceNameValue().isPresent(),
        "The field name must clear the value");
    value.deviceName(vo);
    Assertions.assertSame(holder, value.unsetDeviceName());
    Assertions.assertFalse(value.getDeviceNameValue().isPresent(), "Unset must clear the value");
  }
}
